using System;

class A
{
}

class B
{
    [Obsolete("B to A")]
    public static explicit operator B(A a)
    {
        return null;
    }

    [Obsolete("A to B")]
    public static implicit operator A(B b)
    {
        return null;
    }
}


class Test
{
    static void Main()
    {
        A a = new A();
        B b = (B)a;
        a = b;
        a = (A)(B)(A)b;
    }
}

